public int[] jobScheduling(int[] deadline, int[] profit) {
    int n = deadline.length;
    Integer[] idx = new Integer[n];
    for (int i = 0; i < n; i++) idx[i] = i;
    Arrays.sort(idx, (a, b) -> Integer.compare(profit[b], profit[a])); // profit desc
    int maxD = 0;
    for (int d : deadline) maxD = Math.max(maxD, d);
    boolean[] slot = new boolean[maxD + 1]; // 1-indexed
    int count = 0;
    long totalProfit = 0;
    for (int i = 0; i < n; i++) {
        int j = idx[i];
        for (int t = Math.min(maxD, deadline[j]); t >= 1; t--) {
            if (!slot[t]) {
                slot[t] = true;
                count++;
                totalProfit += profit[j];
                break;
            }
        }
    }
    return new int[]{count, (int) Math.min(totalProfit, Integer.MAX_VALUE)};
}

private int[] parent;

private int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]); // path compression
    return parent[x];
}

public int[] jobScheduling(int[] deadline, int[] profit) {
    int n = deadline.length;
    Integer[] idx = new Integer[n];
    for (int i = 0; i < n; i++) idx[i] = i;
    Arrays.sort(idx, (a, b) -> Integer.compare(profit[b], profit[a])); // profit desc
    int maxD = 0;
    for (int d : deadline) maxD = Math.max(maxD, d);
    parent = new int[maxD + 1];
    for (int t = 0; t <= maxD; t++) parent[t] = t; // slot 0 = sentinel
    int count = 0;
    long totalProfit = 0;
    for (int i = 0; i < n; i++) {
        int j = idx[i];
        int slot = find(Math.min(maxD, deadline[j]));
        if (slot > 0) {
            parent[slot] = slot - 1; // mark used, forward to previous free
            count++;
            totalProfit += profit[j];
        }
    }
    return new int[]{count, (int) Math.min(totalProfit, Integer.MAX_VALUE)};
}

